class Student {
    String name;
    int age;
    static String college = "IIT G";

    public Student(String name, int age) {
        this.name = name;
        this.age = age;
    }

    public void markAttendance() {
        System.out.println(name + " is present");
    }

    public static void changeCollege(String newCollege) {
        college = newCollege;
    }
}

public class Main {
    public static void main(String[] args) {
        Student s1 = new Student("Aditya", 28);
        Student s2 = new Student("Rohit", 25);
        s1.markAttendance();
        Student.changeCollege("IIT Bombay");
        System.out.println(s2.college);
    }
}

class Student {
    String name;
    Student(String name) { this.name = name; }
}

public class Gc {
    public static void main(String[] args) {
        Student a = new Student("A");   // object #1
        Student b = new Student("B");   // object #2
        Student c = a;
        a = null;
        b = new Student("C");           // object #3
        c = b;
    }
}

import java.lang.ref.*;

class Student { }

public class Refs {
    public static void main(String[] args) {
        Student s = new Student();
        WeakReference<Student> w = new WeakReference<>(s);
        PhantomReference<Student> p =
                new PhantomReference<>(s, new ReferenceQueue<>());

        System.gc();

        System.out.println(w.get() == s);
        System.out.println(p.get());
    }
}
